import * as React from "react";
import { graphql, HeadFC, PageProps } from "gatsby";
import { useTranslation } from "gatsby-plugin-react-i18next";
import { FiMail, FiPhoneCall } from "react-icons/fi";
import { ImFacebook2 } from "react-icons/im";
import { SiInstagram, SiTiktok, SiWhatsapp } from "react-icons/si";
import EmailForm from "../components/emailForm";
import Layout from "../components/layout";
import SEO from "../components/seo";
import data from "../data/data.json";
import type { Company } from "../interfaces";
import images from "../images";

const userData = data;

const companyData: Company = {
  whatsapp: data.whatsApp || "",
  companyName: data.name,
  address: data.address,
  city: data.city,
  province: data.province,
  country: "Canada",
  phone: data.phone,
  email: data.email,
  instagram: data.instagram,
  facebook: data.facebook,
  menu: data.menu,
  linkedin: "",
  postalCode: data.postalCode,
  url: data.url,
  whatsApp: data.whatsApp,
};

const pageDescription = [data.address, data.city, data.province]
  .filter(Boolean)
  .join(", ");

function formatPhoneNumber(phoneNumber: string) {
  const cleanedPhoneNumber = phoneNumber.replace(/\D+/g, "");

  if (cleanedPhoneNumber.startsWith("1") && cleanedPhoneNumber.length >= 11) {
    return `+1 ${cleanedPhoneNumber.slice(1, 4)} ${cleanedPhoneNumber.slice(
      4,
      7,
    )} ${cleanedPhoneNumber.slice(7, 11)}`;
  }

  return phoneNumber;
}

const ContactPage: React.FC<PageProps> = () => {
  const { t } = useTranslation();
  const socialLinks = [
    {
      id: "instagram",
      href: data.instagram,
      icon: SiInstagram,
      title: t("contactPage.channels.instagram.title"),
      body: t("contactPage.channels.instagram.body"),
    },
    {
      id: "facebook",
      href: data.facebook,
      icon: ImFacebook2,
      title: t("contactPage.channels.facebook.title"),
      body: t("contactPage.channels.facebook.body"),
    },
    {
      id: "tiktok",
      href: data.tiktok,
      icon: SiTiktok,
      title: t("contactPage.channels.tiktok.title"),
      body: t("contactPage.channels.tiktok.body"),
    },
  ].filter((item) => Boolean(item.href));

  const contactCards = [
    {
      id: "whatsapp",
      href: data.whatsApp,
      icon: SiWhatsapp,
      title: t("contactPage.channels.whatsapp.title"),
      value: t("contactPage.channels.whatsapp.value"),
      body: t("contactPage.channels.whatsapp.body"),
      external: true,
    },
    {
      id: "phone",
      href: `tel:${data.phone}`,
      icon: FiPhoneCall,
      title: t("contactPage.channels.phone.title"),
      value: formatPhoneNumber(data.phone),
      body: t("contactPage.channels.phone.body"),
      external: false,
    },
    {
      id: "email",
      href: `mailto:${data.email}`,
      icon: FiMail,
      title: t("contactPage.channels.email.title"),
      value: data.email,
      body: t("contactPage.channels.email.body"),
      external: false,
    },
  ].filter((item) => Boolean(item.href));

  const responseItems = [
    t("contactPage.response.one"),
    t("contactPage.response.two"),
    t("contactPage.response.three"),
  ];

  return (
    <Layout data={userData}>
      <section className={styles.page}>
        <article className={styles.hero}>
          <img
            className={styles.heroImage}
            src={images.jenny.src}
            alt={images.jenny.alt}
          />
          <div className={styles.heroOverlay}>
            <div className={styles.heroCopy}>
              <p className={styles.eyebrow}>{t("menu.contact")}</p>
              <h1 className={styles.heroTitle}>{t("contactPage.hero.title")}</h1>
              <p className={styles.heroSubtitle}>{t("contactPage.hero.subtitle")}</p>
            </div>
          </div>
        </article>

        <article className={styles.contentSection}>
          <section className={styles.copyColumn}>
            <div className={styles.copyCard}>
              <p className={styles.sectionEyebrow}>{t("contactPage.intro.eyebrow")}</p>
              <h2 className={styles.sectionTitle}>{t("contactPage.intro.title")}</h2>
              <p className={styles.sectionBody}>{t("contactPage.intro.body")}</p>
            </div>

            <div className={styles.cardGrid}>
              {contactCards.map(({ id, href, icon: Icon, title, value, body, external }) => (
                <a
                  key={id}
                  href={href}
                  target={external ? "_blank" : undefined}
                  rel={external ? "noreferrer" : undefined}
                  className={styles.contactCard}
                >
                  <span className={styles.contactIcon}>
                    <Icon />
                  </span>
                  <div>
                    <p className={styles.contactTitle}>{title}</p>
                    <p className={styles.contactValue}>{value}</p>
                    <p className={styles.contactBody}>{body}</p>
                  </div>
                </a>
              ))}
            </div>

            <div className={styles.socialCard}>
              <p className={styles.sectionEyebrow}>{t("contactPage.social.eyebrow")}</p>
              <h2 className={styles.sectionTitle}>{t("contactPage.social.title")}</h2>
              <p className={styles.sectionBody}>{t("contactPage.social.body")}</p>

              <div className={styles.socialGrid}>
                {socialLinks.map(({ id, href, icon: Icon, title, body }) => (
                  <a
                    key={id}
                    href={href}
                    target="_blank"
                    rel="noreferrer"
                    className={styles.socialLinkCard}
                  >
                    <span className={styles.socialIcon}>
                      <Icon />
                    </span>
                    <span>
                      <strong className={styles.socialTitle}>{title}</strong>
                      <span className={styles.socialBody}>{body}</span>
                    </span>
                  </a>
                ))}
              </div>
            </div>

            <div className={styles.stepsCard}>
              <h2 className={styles.sectionTitle}>{t("contactPage.response.title")}</h2>
              <ul className={styles.stepsList}>
                {responseItems.map((item) => (
                  <li key={item} className={styles.stepItem}>
                    {item}
                  </li>
                ))}
              </ul>
            </div>
          </section>

          <section className={styles.formColumn}>
            <EmailForm />
          </section>
        </article>
      </section>
    </Layout>
  );
};

export default ContactPage;

export const Head: HeadFC = ({ pageContext }) => {
  const i18n = (pageContext as
    | {
        i18n?: {
          language?: string;
          languages?: string[];
          defaultLanguage?: string;
          originalPath?: string;
        };
      }
    | undefined)?.i18n;

  return (
    <SEO
      data={companyData}
      title={userData.name}
      description={pageDescription || userData.name}
      schemaName={userData.name}
      pathname="/contact"
      language={i18n?.language}
      languages={i18n?.languages}
      defaultLanguage={i18n?.defaultLanguage}
      originalPath={i18n?.originalPath}
    />
  );
};

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

