import emailjs from "emailjs-com";
import { addDoc, collection, serverTimestamp } from "firebase/firestore";
import type { ContactRequest } from "../interfaces";
import { getEmailJsConfig } from "./emailJsConfig";

const CONTACT_TEMPLATE_ENV_NAME = "GATSBY_EMAILJS_CONTACT_TEMPLATE_ID";
const DEFAULT_CONTACT_COLLECTION = "contact_requests";

async function getFirestoreInstance() {
  const { db } = await import("../../firebaseConfig");
  return db;
}

async function persistContactRequest(request: ContactRequest) {
  try {
    const db = await getFirestoreInstance();

    await addDoc(
      collection(
        db,
        process.env.GATSBY_FIREBASE_CONTACT_COLLECTION || DEFAULT_CONTACT_COLLECTION,
      ),
      {
        ...request,
        createdAt: serverTimestamp(),
        createdAtIso: new Date().toISOString(),
      },
    );
  } catch (error) {
    console.error("Failed to persist contact request in Firebase.", error);
  }
}

function buildEmailPayload(request: ContactRequest) {
  return {
    name: request.name,
    phone: request.phone,
    email: request.email,
    comments: request.comments || "-",
    reply_to: request.email,
    submitted_at: new Date().toISOString(),
    subject: `New contact request from ${request.name}`,
  };
}

export async function submitContactRequest(
  request: ContactRequest,
  recaptchaToken?: string,
) {
  const emailJsConfig = getEmailJsConfig(CONTACT_TEMPLATE_ENV_NAME);

  if (!emailJsConfig) {
    throw new Error("CONTACT_EMAIL_NOT_CONFIGURED");
  }

  await emailjs.send(
    emailJsConfig.serviceId,
    emailJsConfig.templateId,
    {
      ...buildEmailPayload(request),
      recaptcha_token: recaptchaToken || "",
    },
    emailJsConfig.publicKey,
  );

  await persistContactRequest(request);
}
